"""FlyDSL BF16 GEMM ``out = a @ b.T``: aiter's single-launch FlyDSL HGEMM with a tile shape chosen from ``m``.

Each workgroup walks the whole K (no split-K); A goes through LDS, and B too on the largest-m tile only.
"""

import functools

import flydsl.expr as fx
import torch
from aiter.ops.flydsl.kernels.splitk_hgemm import compile_hgemm_kernel
from aiter.ops.flydsl.kernels.tensor_shim import _run_compiled, ptr_arg


def _config(m):
    if m <= 16:
        return dict(TILE_M=16, TILE_N=32, TILE_K=256, BLOCK_M_WARPS=1, BLOCK_N_WARPS=1)
    if m <= 64:
        return dict(TILE_M=32, TILE_N=32, TILE_K=256, BLOCK_M_WARPS=1, BLOCK_N_WARPS=2)
    return dict(TILE_M=32, TILE_N=64, TILE_K=128, BLOCK_M_WARPS=1, BLOCK_N_WARPS=4, STAGES=3, B_TO_LDS=True)


@functools.cache
def _launch_for(m, n, k):
    kernel = compile_hgemm_kernel("bf16", n, k, **_config(m))

    def launch(a, b, out):
        stream = fx.Stream(torch._C._cuda_getCurrentRawStream(a.device.index))
        pb = ptr_arg(b)
        # pb also fills the bias, semaphore and signal slots, never read without bias or split-K.
        _run_compiled(kernel, ptr_arg(out), ptr_arg(a), pb, pb, m, pb, pb, stream)

    return launch


def run(*, a, b, trans_b, bias, out_dtype, out):
    _launch_for(a.shape[0], b.shape[0], a.shape[1])(a, b, out)
